-- 0008_media: the media library (task A6, docs/CUSTOMIZATION_PLAN.md sections 4.1 and 13).
--
-- Additive only: three new tables and a seed of one row per image already in
-- public/images. Nothing on the public site reads these tables yet.
--
--   media        one row per photo: a repository image (served from /images by
--                the site itself) or an upload (variants in Supabase Storage);
--                alt text, provenance, and whether it may be placed.
--   media_files  one row per stored version of an upload's file; replacing a
--                photo adds a row and retires the old one, whose objects are
--                deleted only when nothing pins that version.
--   media_usage  who uses a photo (pages, sections, collection items, from
--                later tasks); a photo in use cannot be deleted or unpublished.

create table if not exists media (
  id text primary key,
  origin text not null,
  repo_path text,
  current_file_id text,
  original_filename text,
  width integer,
  height integer,
  bytes bigint,
  alt text not null default '',
  provenance jsonb not null default '{}'::jsonb,
  provenance_status text not null default 'incomplete',
  published boolean not null default false,
  created_at timestamptz not null default now(),
  created_by text,
  updated_at timestamptz not null default now(),
  updated_by text,
  deleted_at timestamptz,
  deleted_by text,
  constraint media_origin_check check (origin in ('repository', 'upload')),
  constraint media_repo_path_check check ((origin = 'repository') = (repo_path is not null)),
  constraint media_provenance_status_check check (provenance_status in ('complete', 'incomplete')),
  -- Only a photo with complete provenance can be published.
  constraint media_published_needs_provenance check (not published or provenance_status = 'complete')
);

create unique index if not exists media_repo_path_idx on media (repo_path) where repo_path is not null;
create index if not exists media_created_idx on media (created_at desc, id desc) where deleted_at is null;

create table if not exists media_files (
  id text primary key,
  media_id text not null references media (id),
  width integer not null,
  height integer not null,
  sha256 text not null,
  format text not null,
  variants jsonb not null,
  analysis_key text not null,
  analysis_width integer not null,
  analysis_height integer not null,
  created_at timestamptz not null default now(),
  created_by text,
  retired_at timestamptz,
  purged_at timestamptz,
  constraint media_files_format_check check (format in ('jpeg', 'png', 'webp'))
);

create index if not exists media_files_media_idx on media_files (media_id);

create table if not exists media_usage (
  id text primary key,
  media_id text not null references media (id),
  -- Set when a kept version pins one stored file, so replacing the photo keeps it.
  file_id text references media_files (id),
  owner_kind text not null,
  owner_id text not null,
  owner_state text not null,
  field text,
  created_at timestamptz not null default now(),
  constraint media_usage_state_check check (owner_state in ('draft', 'published', 'kept'))
);

create index if not exists media_usage_media_idx on media_usage (media_id);
create index if not exists media_usage_file_idx on media_usage (file_id) where file_id is not null;

